  <style>
    *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

    :root {
      --color-primary: #171717;
      --color-accent: #0072F5;
      --color-bg: #FAFAFA;
      --color-white: #FFFFFF;
      --color-gray-50: #F9FAFB;
      --color-gray-100: #F3F4F6;
      --color-gray-200: #E5E7EB;
      --color-gray-300: #D1D5DB;
      --color-gray-400: #9CA3AF;
      --color-gray-500: #6B7280;
      --color-gray-600: #4B5563;
      --color-gray-700: #374151;
      --color-gray-800: #1F2937;
      --color-gray-900: #111827;
      --font-sans: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
      --shadow-sm: 0 1px 2px rgba(0,0,0,0.05);
      --shadow-md: 0 4px 6px -1px rgba(0,0,0,0.07), 0 2px 4px -2px rgba(0,0,0,0.05);
      --shadow-lg: 0 10px 15px -3px rgba(0,0,0,0.08), 0 4px 6px -4px rgba(0,0,0,0.05);
      --radius-sm: 6px;
      --radius-md: 8px;
      --radius-lg: 12px;
      --radius-xl: 16px;
      --max-width: 1200px;
    }

    html { font-size: 16px; -webkit-font-smoothing: antialiased; -moz-osx-font-smoothing: grayscale; }

    body {
      font-family: var(--font-sans);
      color: var(--color-primary);
      background: var(--color-bg);
      line-height: 1.6;
    }

    a { color: inherit; text-decoration: none; }

    /* ── Header ── */
    .header {
      position: sticky;
      top: 0;
      z-index: 100;
      background: rgba(255,255,255,0.92);
      backdrop-filter: blur(12px);
      -webkit-backdrop-filter: blur(12px);
      border-bottom: 1px solid var(--color-gray-200);
    }

    .header-inner {
      max-width: var(--max-width);
      margin: 0 auto;
      padding: 0 24px;
      height: 64px;
      display: flex;
      align-items: center;
      justify-content: space-between;
    }

    .header-left {
      display: flex;
      align-items: center;
      gap: 32px;
    }

    .logo {
      display: flex;
      align-items: center;
      gap: 8px;
      font-weight: 700;
      font-size: 1.125rem;
      color: var(--color-primary);
    }

    .logo-icon {
      width: 28px;
      height: 28px;
      background: var(--color-primary);
      border-radius: 6px;
      display: flex;
      align-items: center;
      justify-content: center;
    }

    .logo-icon svg { width: 16px; height: 16px; }

    .nav-links {
      display: flex;
      align-items: center;
      gap: 4px;
      list-style: none;
    }

    .nav-item {
      position: relative;
    }

    .nav-link {
      display: flex;
      align-items: center;
      gap: 4px;
      padding: 8px 12px;
      font-size: 0.875rem;
      font-weight: 500;
      color: var(--color-gray-700);
      border-radius: var(--radius-sm);
      transition: background 0.15s, color 0.15s;
      cursor: pointer;
      border: none;
      background: none;
      font-family: inherit;
    }

    .nav-link:hover { background: var(--color-gray-100); color: var(--color-primary); }

    .nav-link svg { width: 14px; height: 14px; transition: transform 0.2s; }
    .nav-item.open .nav-link svg { transform: rotate(180deg); }

    .header-right {
      display: flex;
      align-items: center;
      gap: 8px;
    }

    .btn-ask-ai {
      display: flex;
      align-items: center;
      gap: 6px;
      padding: 7px 14px;
      font-size: 0.8125rem;
      font-weight: 600;
      color: var(--color-accent);
      border: 1px solid var(--color-accent);
      border-radius: var(--radius-md);
      background: none;
      cursor: pointer;
      transition: background 0.15s, color 0.15s;
    }

    .btn-ask-ai:hover { background: var(--color-accent); color: #fff; }

    .btn-login {
      padding: 7px 14px;
      font-size: 0.8125rem;
      font-weight: 500;
      color: var(--color-gray-700);
      background: none;
      border: none;
      cursor: pointer;
      border-radius: var(--radius-sm);
    }

    .btn-login:hover { color: var(--color-primary); }

    .btn-signup {
      padding: 7px 16px;
      font-size: 0.8125rem;
      font-weight: 600;
      color: #fff;
      background: var(--color-primary);
      border: none;
      border-radius: var(--radius-md);
      cursor: pointer;
      transition: opacity 0.15s;
    }

    .btn-signup:hover { opacity: 0.88; }

    /* ── Mega Menus ── */
    .mega-menu {
      position: absolute;
      top: 100%;
      left: 50%;
      transform: translateX(-50%);
      min-width: 640px;
      background: #fff;
      border: 1px solid var(--color-gray-200);
      border-radius: var(--radius-lg);
      box-shadow: var(--shadow-lg);
      padding: 24px;
      opacity: 0;
      visibility: hidden;
      pointer-events: none;
      transition: opacity 0.2s, transform 0.2s;
      transform: translateX(-50%) translateY(4px);
    }

    .nav-item.open .mega-menu {
      opacity: 1;
      visibility: visible;
      pointer-events: auto;
      transform: translateX(-50%) translateY(0);
    }

    .mega-menu-grid {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 8px;
    }

    .mega-menu-grid.two-col { grid-template-columns: repeat(2, 1fr); }

    .mega-col-heading {
      font-size: 0.6875rem;
      font-weight: 700;
      text-transform: uppercase;
      letter-spacing: 0.06em;
      color: var(--color-gray-400);
      padding: 8px 12px 6px;
    }

    .mega-link {
      display: block;
      padding: 8px 12px;
      border-radius: var(--radius-sm);
      transition: background 0.15s;
    }

    .mega-link:hover { background: var(--color-gray-50); }

    .mega-link-title {
      font-size: 0.875rem;
      font-weight: 600;
      color: var(--color-primary);
    }

    .mega-link-desc {
      font-size: 0.75rem;
      color: var(--color-gray-500);
      line-height: 1.4;
      margin-top: 2px;
    }

    /* Resources mega menu */
    .mega-menu-resources { min-width: 400px; }
    .mega-menu-resources .mega-menu-grid { grid-template-columns: repeat(3, 1fr); }

    /* ── Page Title ── */
    .page-title-section {
      max-width: var(--max-width);
      margin: 0 auto;
      padding: 48px 24px 0;
    }

    .page-title {
      font-size: 2.5rem;
      font-weight: 800;
      letter-spacing: -0.03em;
      color: var(--color-primary);
    }

    .page-subtitle {
      font-size: 1.0625rem;
      color: var(--color-gray-500);
      margin-top: 8px;
      max-width: 560px;
    }

    /* ── Category Filters ── */
    .filters-section {
      max-width: var(--max-width);
      margin: 0 auto;
      padding: 24px 24px 0;
    }

    .filters-row {
      display: flex;
      align-items: center;
      gap: 12px;
      flex-wrap: wrap;
    }

    .filter-pills {
      display: flex;
      gap: 6px;
      flex-wrap: wrap;
      flex: 1;
    }

    .filter-pill {
      padding: 6px 16px;
      font-size: 0.8125rem;
      font-weight: 500;
      color: var(--color-gray-600);
      background: var(--color-white);
      border: 1px solid var(--color-gray-200);
      border-radius: 999px;
      cursor: pointer;
      transition: all 0.15s;
      font-family: inherit;
    }

    .filter-pill:hover {
      border-color: var(--color-gray-300);
      color: var(--color-primary);
    }

    .filter-pill.active {
      background: var(--color-primary);
      color: #fff;
      border-color: var(--color-primary);
    }

    .search-box {
      position: relative;
      flex-shrink: 0;
    }

    .search-box svg {
      position: absolute;
      left: 12px;
      top: 50%;
      transform: translateY(-50%);
      width: 16px;
      height: 16px;
      color: var(--color-gray-400);
    }

    .search-input {
      padding: 8px 14px 8px 36px;
      font-size: 0.8125rem;
      border: 1px solid var(--color-gray-200);
      border-radius: 999px;
      background: var(--color-white);
      width: 220px;
      outline: none;
      font-family: inherit;
      color: var(--color-primary);
      transition: border-color 0.15s, box-shadow 0.15s;
    }

    .search-input::placeholder { color: var(--color-gray-400); }
    .search-input:focus {
      border-color: var(--color-accent);
      box-shadow: 0 0 0 3px rgba(0,114,245,0.12);
    }

    /* ── Featured Articles ── */
    .featured-section {
      max-width: var(--max-width);
      margin: 0 auto;
      padding: 40px 24px 0;
    }

    .featured-grid {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 20px;
    }

    .featured-card {
      background: var(--color-white);
      border: 1px solid var(--color-gray-200);
      border-radius: var(--radius-xl);
      overflow: hidden;
      transition: box-shadow 0.2s, border-color 0.2s, transform 0.2s;
      cursor: pointer;
      display: flex;
      flex-direction: column;
    }

    .featured-card:hover {
      box-shadow: var(--shadow-lg);
      border-color: var(--color-gray-300);
      transform: translateY(-2px);
    }

    .featured-card:first-child {
      grid-row: 1 / 3;
    }

    .featured-card:first-child .featured-image {
      height: 260px;
    }

    .featured-image {
      height: 160px;
      background: linear-gradient(135deg, var(--color-gray-100) 0%, var(--color-gray-200) 100%);
      position: relative;
      overflow: hidden;
    }

    .featured-card:nth-child(1) .featured-image {
      background: linear-gradient(135deg, #0a1628 0%, #1a3a5c 40%, #0072F5 100%);
    }
    .featured-card:nth-child(2) .featured-image {
      background: linear-gradient(135deg, #1a1a2e 0%, #16213e 40%, #0f3460 100%);
    }
    .featured-card:nth-child(3) .featured-image {
      background: linear-gradient(135deg, #2d1b69 0%, #11998e 100%);
    }

    .featured-image-label {
      position: absolute;
      bottom: 16px;
      left: 20px;
      color: #fff;
      font-size: 0.6875rem;
      font-weight: 700;
      text-transform: uppercase;
      letter-spacing: 0.08em;
      opacity: 0.7;
    }

    .featured-stat {
      position: absolute;
      top: 16px;
      right: 16px;
      background: rgba(0,0,0,0.5);
      backdrop-filter: blur(8px);
      color: #fff;
      padding: 6px 12px;
      border-radius: 999px;
      font-size: 0.75rem;
      font-weight: 600;
    }

    .featured-body {
      padding: 24px;
      flex: 1;
      display: flex;
      flex-direction: column;
    }

    .featured-meta {
      display: flex;
      align-items: center;
      gap: 8px;
      font-size: 0.8125rem;
      color: var(--color-gray-500);
      margin-bottom: 10px;
    }

    .featured-tag {
      font-size: 0.6875rem;
      font-weight: 600;
      color: var(--color-accent);
      text-transform: uppercase;
      letter-spacing: 0.04em;
    }

    .featured-title {
      font-size: 1.375rem;
      font-weight: 700;
      letter-spacing: -0.02em;
      line-height: 1.3;
      color: var(--color-primary);
      margin-bottom: 10px;
    }

    .featured-card:first-child .featured-title { font-size: 1.625rem; }

    .featured-excerpt {
      font-size: 0.9375rem;
      color: var(--color-gray-600);
      line-height: 1.6;
      flex: 1;
    }

    .featured-author {
      display: flex;
      align-items: center;
      gap: 10px;
      margin-top: 16px;
      padding-top: 16px;
      border-top: 1px solid var(--color-gray-100);
    }

    .author-avatar {
      width: 32px;
      height: 32px;
      border-radius: 50%;
      background: var(--color-gray-200);
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 0.75rem;
      font-weight: 700;
      color: var(--color-gray-500);
      flex-shrink: 0;
    }

    .author-name {
      font-size: 0.8125rem;
      font-weight: 600;
      color: var(--color-primary);
    }

    .author-date {
      font-size: 0.75rem;
      color: var(--color-gray-400);
    }

    /* ── Latest News ── */
    .latest-section {
      max-width: var(--max-width);
      margin: 0 auto;
      padding: 56px 24px 0;
    }

    .section-heading {
      font-size: 1.5rem;
      font-weight: 700;
      letter-spacing: -0.02em;
      margin-bottom: 24px;
    }

    .posts-grid {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 20px;
    }

    .post-card {
      background: var(--color-white);
      border: 1px solid var(--color-gray-200);
      border-radius: var(--radius-lg);
      padding: 24px;
      transition: box-shadow 0.2s, border-color 0.2s, transform 0.2s;
      cursor: pointer;
      display: flex;
      flex-direction: column;
    }

    .post-card:hover {
      box-shadow: var(--shadow-md);
      border-color: var(--color-gray-300);
      transform: translateY(-1px);
    }

    .post-tag {
      display: inline-block;
      font-size: 0.6875rem;
      font-weight: 600;
      color: var(--color-accent);
      text-transform: uppercase;
      letter-spacing: 0.04em;
      margin-bottom: 10px;
    }

    .post-date {
      font-size: 0.75rem;
      color: var(--color-gray-400);
      margin-bottom: 8px;
    }

    .post-title {
      font-size: 1.0625rem;
      font-weight: 700;
      letter-spacing: -0.01em;
      line-height: 1.35;
      color: var(--color-primary);
      margin-bottom: 8px;
    }

    .post-excerpt {
      font-size: 0.875rem;
      color: var(--color-gray-500);
      line-height: 1.55;
      flex: 1;
      margin-bottom: 16px;
      display: -webkit-box;
      -webkit-line-clamp: 3;
      -webkit-box-orient: vertical;
      overflow: hidden;
    }

    .post-author {
      display: flex;
      align-items: center;
      gap: 8px;
      padding-top: 14px;
      border-top: 1px solid var(--color-gray-100);
    }

    .post-author .author-avatar { width: 28px; height: 28px; font-size: 0.6875rem; }

    .post-author .author-name { font-size: 0.75rem; }

    /* No results */
    .no-results {
      grid-column: 1 / -1;
      text-align: center;
      padding: 64px 24px;
    }

    .no-results-icon {
      width: 48px;
      height: 48px;
      margin: 0 auto 16px;
      color: var(--color-gray-300);
    }

    .no-results-text {
      font-size: 1rem;
      color: var(--color-gray-500);
      max-width: 380px;
      margin: 0 auto;
      line-height: 1.6;
    }

    /* Show more */
    .show-more-wrap {
      text-align: center;
      padding: 40px 0 16px;
    }

    .btn-show-more {
      padding: 12px 32px;
      font-size: 0.875rem;
      font-weight: 600;
      color: var(--color-primary);
      background: var(--color-white);
      border: 1px solid var(--color-gray-200);
      border-radius: var(--radius-md);
      cursor: pointer;
      transition: all 0.15s;
      font-family: inherit;
    }

    .btn-show-more:hover {
      border-color: var(--color-gray-300);
      box-shadow: var(--shadow-sm);
    }

    /* ── CTA Banner ── */
    .cta-section {
      max-width: var(--max-width);
      margin: 0 auto;
      padding: 64px 24px 0;
    }

    .cta-banner {
      background: var(--color-primary);
      border-radius: var(--radius-xl);
      padding: 56px 48px;
      display: flex;
      justify-content: space-between;
      align-items: center;
      gap: 32px;
    }

    .cta-content { max-width: 540px; }

    .cta-headline {
      font-size: 1.5rem;
      font-weight: 700;
      color: #fff;
      line-height: 1.35;
      letter-spacing: -0.02em;
    }

    .cta-headline strong { color: var(--color-accent); }

    .cta-sub {
      margin-top: 12px;
      font-size: 0.9375rem;
      color: rgba(255,255,255,0.6);
      line-height: 1.5;
    }

    .cta-sub a { color: var(--color-accent); font-weight: 600; }
    .cta-sub a:hover { text-decoration: underline; }

    .cta-actions {
      display: flex;
      flex-direction: column;
      gap: 12px;
      flex-shrink: 0;
    }

    .btn-primary {
      display: inline-flex;
      align-items: center;
      justify-content: center;
      gap: 8px;
      padding: 12px 28px;
      font-size: 0.9375rem;
      font-weight: 600;
      color: var(--color-primary);
      background: #fff;
      border: none;
      border-radius: var(--radius-md);
      cursor: pointer;
      transition: opacity 0.15s;
      font-family: inherit;
    }

    .btn-primary:hover { opacity: 0.92; }

    .btn-secondary {
      display: inline-flex;
      align-items: center;
      justify-content: center;
      gap: 8px;
      padding: 12px 28px;
      font-size: 0.9375rem;
      font-weight: 600;
      color: #fff;
      background: rgba(255,255,255,0.12);
      border: 1px solid rgba(255,255,255,0.2);
      border-radius: var(--radius-md);
      cursor: pointer;
      transition: background 0.15s;
      font-family: inherit;
    }

    .btn-secondary:hover { background: rgba(255,255,255,0.18); }

    /* Enterprise block */
    .enterprise-block {
      margin-top: 24px;
      padding: 24px 32px;
      background: var(--color-gray-50);
      border: 1px solid var(--color-gray-200);
      border-radius: var(--radius-lg);
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 24px;
    }

    .enterprise-text {
      font-size: 0.9375rem;
      color: var(--color-gray-600);
    }

    .btn-enterprise {
      padding: 10px 22px;
      font-size: 0.875rem;
      font-weight: 600;
      color: var(--color-primary);
      background: var(--color-white);
      border: 1px solid var(--color-gray-200);
      border-radius: var(--radius-md);
      cursor: pointer;
      transition: all 0.15s;
      white-space: nowrap;
      font-family: inherit;
    }

