    // ── State ──
    let activeCategory = 'all';
    let searchQuery = '';
    let visibleCount = 6;

    // ── Render Posts ──
    function renderPosts() {
      const grid = document.getElementById('postsGrid');
      const filtered = allPosts.filter(post => {
        const matchCategory = activeCategory === 'all' || post.category === activeCategory;
        const q = searchQuery.toLowerCase();
        const matchSearch = !q ||
          post.title.toLowerCase().includes(q) ||
          post.excerpt.toLowerCase().includes(q) ||
          post.searchable.toLowerCase().includes(q) ||
          post.author.toLowerCase().includes(q) ||
          post.tag.toLowerCase().includes(q);
        return matchCategory && matchSearch;
      });

      const toShow = filtered.slice(0, visibleCount);

      if (toShow.length === 0) {
        grid.innerHTML = `
          <div class="no-results">
            <svg class="no-results-icon" viewBox="0 0 24 24" fill="none"><path d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"/></svg>
            <p class="no-results-text">No results found at this time. Try again with a different keyword.</p>
          </div>`;
        document.getElementById('showMoreWrap').style.display = 'none';
        return;
      }

      grid.innerHTML = toShow.map(post => `
        <article class="post-card">
          <span class="post-tag">${post.tag}</span>
          <div class="post-date">${post.date}</div>
          <h3 class="post-title">${post.title}</h3>
          <p class="post-excerpt">${post.excerpt}</p>
          <div class="post-author">
            <div class="author-avatar">${post.initials}</div>
            <span class="author-name">${post.author}</span>
          </div>
        </article>
      `).join('');

      const wrap = document.getElementById('showMoreWrap');
      if (filtered.length > visibleCount) {
        wrap.style.display = '';
      } else {
        wrap.style.display = 'none';
      }
    }

    // ── Filter Featured ──
    function filterFeatured() {
      const cards = document.querySelectorAll('#featuredGrid .featured-card');
      const q = searchQuery.toLowerCase();
      let anyVisible = false;
      cards.forEach(card => {
        const cats = card.dataset.categories || '';
        const searchable = card.dataset.searchable || '';
        const title = card.querySelector('.featured-title')?.textContent.toLowerCase() || '';
        const excerpt = card.querySelector('.featured-excerpt')?.textContent.toLowerCase() || '';

        const matchCategory = activeCategory === 'all' || cats.split(' ').includes(activeCategory);
        const matchSearch = !q || title.includes(q) || excerpt.includes(q) || searchable.includes(q);

        if (matchCategory && matchSearch) {
          card.style.display = '';
          anyVisible = true;
        } else {
          card.style.display = 'none';
        }
      });
      document.getElementById('featuredSection').style.display = anyVisible ? '' : 'none';
    }

    // ── Category Pill Click ──
    document.getElementById('filterPills').addEventListener('click', (e) => {
      const pill = e.target.closest('.filter-pill');
      if (!pill) return;
      document.querySelectorAll('.filter-pill').forEach(p => p.classList.remove('active'));
      pill.classList.add('active');
      activeCategory = pill.dataset.category;
      visibleCount = 6;
      renderPosts();
      filterFeatured();
    });

    // ── Search Input ──
    document.getElementById('searchInput').addEventListener('input', (e) => {
      searchQuery = e.target.value.trim();
      visibleCount = 6;
      renderPosts();
      filterFeatured();
    });

    // ── Show More ──
    document.getElementById('showMoreBtn').addEventListener('click', () => {
      visibleCount += 6;
      renderPosts();
    });

    // ── Dropdown Menus ──
    function toggleDropdown(name) {
      const item = document.querySelector(`[data-dropdown="${name}"]`);
      const isOpen = item.classList.contains('open');
      // Close all dropdowns first
      document.querySelectorAll('.nav-item').forEach(i => i.classList.remove('open'));
      if (!isOpen) item.classList.add('open');
    }

    // Close dropdowns when clicking outside
    document.addEventListener('click', (e) => {
      if (!e.target.closest('.nav-item')) {
        document.querySelectorAll('.nav-item').forEach(i => i.classList.remove('open'));
      }
    });

    // ── Init ──
    renderPosts();
  </script>

